import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ServiceRegistryService } from '../../services/service-registry.service';
import { ParameterLibraryService } from '../../services/parameter-library.service';
import { ServiceDefinition, ServiceParameter } from '../../models/service-definition.model';

@Component({
  selector: 'app-service-manager',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './service-manager.html',
  styleUrl: './service-manager.scss'
})
export class ServiceManager {
  private registry = inject(ServiceRegistryService);
  readonly paramLibrary = inject(ParameterLibraryService);

  readonly services = this.registry.allServices;
  readonly parameterTypes = this.paramLibrary.allTypes;

  /** Currently selected service for viewing/editing */
  selectedServiceId = signal<string | null>(null);

  /** Whether we're in "add new" mode */
  addingNew = signal(false);

  /** New service form data */
  newService = signal<Partial<ServiceDefinition>>({
    programName: '',
    displayName: '',
    description: '',
    parameters: []
  });

  /** New parameter being added */
  newParam = signal<Partial<ServiceParameter>>({
    position: 1,
    parameterTypeKey: '',
    required: false
  });

  selectService(id: string): void {
    this.selectedServiceId.set(id);
    this.addingNew.set(false);
  }

  getSelectedService(): ServiceDefinition | undefined {
    const id = this.selectedServiceId();
    return id ? this.registry.getService(id) : undefined;
  }

  startAddNew(): void {
    this.addingNew.set(true);
    this.selectedServiceId.set(null);
    this.newService.set({
      programName: '',
      displayName: '',
      description: '',
      parameters: []
    });
  }

  cancelAddNew(): void {
    this.addingNew.set(false);
  }

  addParameterToNew(): void {
    const np = this.newParam();
    if (!np.parameterTypeKey) return;

    this.newService.update(svc => ({
      ...svc,
      parameters: [
        ...(svc.parameters || []),
        {
          position: (svc.parameters?.length || 0) + 1,
          parameterTypeKey: np.parameterTypeKey!,
          required: np.required || false
        }
      ]
    }));

    this.newParam.set({ position: 1, parameterTypeKey: '', required: false });
  }

  removeParameterFromNew(index: number): void {
    this.newService.update(svc => ({
      ...svc,
      parameters: (svc.parameters || [])
        .filter((_, i) => i !== index)
        .map((p, i) => ({ ...p, position: i + 1 }))
    }));
  }

  saveNewService(): void {
    const svc = this.newService();
    if (!svc.programName || !svc.displayName) return;

    const service: ServiceDefinition = {
      id: svc.programName!.toLowerCase().replace(/\s+/g, '_'),
      programName: svc.programName!,
      displayName: svc.displayName!,
      description: svc.description || '',
      parameters: svc.parameters as ServiceParameter[] || [],
      builtIn: false
    };

    this.registry.addService(service);
    this.addingNew.set(false);
    this.selectedServiceId.set(service.id);
  }

  removeService(id: string): void {
    this.registry.removeService(id);
    if (this.selectedServiceId() === id) {
      this.selectedServiceId.set(null);
    }
  }

  exportServices(): void {
    const json = this.registry.exportServices();
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'dwsv-services.json';
    a.click();
    URL.revokeObjectURL(url);
  }

  importServices(event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      try {
        const result = this.registry.importServices(reader.result as string);
        this.importMessage.set(`Imported ${result.imported}, skipped ${result.skipped} (duplicate IDs)`);
        setTimeout(() => this.importMessage.set(null), 3000);
      } catch {
        this.importMessage.set('Error: Invalid JSON file');
        setTimeout(() => this.importMessage.set(null), 3000);
      }
    };
    reader.readAsText(file);
  }

  importMessage = signal<string | null>(null);

  /** Update a field on the new service form */
  updateNewServiceField(field: string, value: any): void {
    this.newService.update(s => ({ ...s, [field]: value }));
  }

  /** Update a field on the new parameter form */
  updateNewParamField(field: string, value: any): void {
    this.newParam.update(p => ({ ...p, [field]: value }));
  }

  /** Get the label for a parameter type key */
  getParamTypeLabel(key: string): string {
    return this.paramLibrary.getType(key)?.label || key;
  }
}
